<script setup>
import {computed,nextTick,onUnmounted,ref,watch} from 'vue'
import {interactionTrace as trace} from '../interaction-trace.js'
import {actions,screens} from '../trace-catalog.js'
import {trapFocus} from '../modal-focus'
const open=ref(false),snapshot=ref(trace.snapshot()),selected=ref(''),tab=ref('timeline'),screenFilter=ref(''),trigger=ref(null),closeButton=ref(null)
const refresh=()=>{snapshot.value=trace.snapshot();if(!snapshot.value.sessions.some(s=>s.id===selected.value))selected.value=snapshot.value.sessions.at(-1)?.id||''}
const unsubscribe=trace.subscribe(refresh)
onUnmounted(unsubscribe)
const session=computed(()=>snapshot.value.sessions.find(s=>s.id===selected.value))
const locations=computed(()=>[...new Set((session.value?.events||[]).map(location))])
const events=computed(()=>(session.value?.events||[]).filter(e=>!screenFilter.value||location(e)===screenFilter.value))
const points=computed(()=>events.value.filter(e=>e.position))
const serialized=computed(()=>JSON.stringify({schema_version:1,session_id:session.value?.id||null,events:events.value},null,2))
function location(e){return `${e.screen}/${e.step}${e.overlay?' · '+e.overlay:''}`}
function description(e){return e.type==='interaction'?actions[e.action]:({'session.start':'Sesión iniciada','session.end':'Sesión terminada: '+e.reason,'screen.enter':'Entró a pantalla/paso','screen.leave':'Salió de pantalla/paso','overlay.change':'Ventana: '+(e.overlay||'cerrada'),'operation.start':'Inició '+e.operation,'operation.end':`${e.operation} → ${e.outcome}`}[e.type]||e.type)}
watch(selected,()=>{screenFilter.value=''})
watch(open,async value=>{if(value){await nextTick();closeButton.value?.focus()}else{await nextTick();trigger.value?.focus()}})
</script>
<template>
  <div data-trace-ignore class="trace-tools">
    <button ref="trigger" class="trace-trigger" @click="open=true">TRAZABILIDAD · DESARROLLO <span>{{snapshot.sessions.length}}</span></button>
    <div v-if="open" class="trace-backdrop" @keydown.esc.stop="open=false" @keydown="trapFocus">
      <section class="trace-panel" role="dialog" aria-modal="true" aria-labelledby="trace-title">
        <header class="trace-header"><div><small>DIAGNÓSTICO LOCAL · SIN CONEXIÓN A TU API</small><h2 id="trace-title">Recorrido de la sesión</h2></div><button ref="closeButton" aria-label="Cerrar trazabilidad" @click="open=false">✕</button></header>
        <p class="trace-notice">Solo memoria de esta ventana. Comienza después del inicio de sesión y se pierde al recargar. No contiene matrícula, PIN, correo, folios ni texto escrito.</p>
        <div class="trace-toolbar"><label>Sesión<select v-model="selected" aria-label="Sesión de trazabilidad"><option v-if="!snapshot.sessions.length" value="">Todavía no hay sesiones</option><option v-for="(s,index) in snapshot.sessions" :key="s.id" :value="s.id">Sesión {{index+1}} · {{s.id.slice(0,8)}} · {{s.ended_at?'cerrada':'activa'}}</option></select></label><label>Pantalla / paso<select v-model="screenFilter" aria-label="Filtrar pantalla"><option value="">Todos</option><option v-for="value in locations" :key="value" :value="value">{{value}}</option></select></label><button :disabled="!!snapshot.active_session" @click="trace.clear()">Limpiar memoria</button></div>
        <p class="trace-count" role="status">{{events.length}} eventos visibles · {{snapshot.pending}} pendientes de una futura integración. {{snapshot.active_session?'Hay una sesión activa.':''}}</p>
        <p v-if="session?.dropped||snapshot.evicted_sessions" class="trace-loss">Límite de memoria: {{session?.dropped||0}} eventos antiguos retirados de esta sesión; {{snapshot.evicted_sessions}} sesiones anteriores retiradas. Este registro puede ser incompleto.</p>
        <nav class="trace-tabs" aria-label="Vista de trazabilidad"><button :aria-pressed="tab==='timeline'" @click="tab='timeline'">Secuencia</button><button :aria-pressed="tab==='map'" @click="tab='map'">Mapa de toques</button><button :aria-pressed="tab==='json'" @click="tab='json'">Contrato JSON</button></nav>
        <div v-if="!session" class="trace-empty">Cierra este visor, inicia sesión en el kiosco y utiliza sus servicios. Después vuelve aquí para revisar el recorrido.</div>
        <div v-else-if="tab==='timeline'" class="trace-table"><table><thead><tr><th>Orden</th><th>Tiempo</th><th>Pantalla</th><th>Acción / resultado</th></tr></thead><tbody><tr v-for="event in events" :key="event.event_id"><td>{{event.sequence}}</td><td>+{{(event.elapsed_ms/1000).toFixed(1)}} s</td><td>{{screens[event.screen]}}<small>{{event.step}}{{event.overlay?' · '+event.overlay:''}}</small></td><td>{{description(event)}}<small>{{event.input||event.type}}{{event.item_index!==undefined?' · opción '+(event.item_index+1):''}}{{event.http_status?' · HTTP '+event.http_status:''}}{{event.after_session_end?' · respuesta posterior al cierre':''}}</small></td></tr></tbody></table></div>
        <div v-else-if="tab==='map'" class="trace-map-wrap"><p>Selecciona una pantalla/paso para comparar toques. Posiciones relativas a la ventana; esquema sin capturas de pantalla. El teclado escrito y sus teclas quedan excluidos.</p><div class="trace-map" aria-label="Mapa esquemático de toques"><span v-for="event in points" :key="event.event_id" class="trace-dot" :style="{left:event.position.x*100+'%',top:event.position.y*100+'%'}" :title="event.sequence+' · '+description(event)">{{event.sequence}}</span><p v-if="!points.length">No hay toques con posición en esta vista.</p></div></div>
        <pre v-else class="trace-json" data-testid="trace-json">{{serialized}}</pre>
      </section>
    </div>
  </div>
</template>
<style scoped>
.trace-tools{font-family:Arial,sans-serif;color:#172b49;font-size:14px}.trace-trigger{position:fixed;right:12px;bottom:12px;z-index:1200;background:#172b49;color:white;border:2px solid #fff;border-radius:9px;padding:12px 14px;font-weight:700;box-shadow:0 2px 12px #0003}.trace-trigger span{background:#fff;color:#172b49;border-radius:12px;padding:2px 6px;margin-left:7px}.trace-backdrop{position:fixed;inset:0;background:#0c1738aa;z-index:1300;display:grid;place-items:center;padding:20px}.trace-panel{display:flex;flex-direction:column;background:#fff;border-radius:16px;width:min(1120px,96vw);max-height:92vh;overflow:hidden;box-shadow:0 20px 80px #0005}.trace-header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;background:#172b49;color:white}.trace-header h2{font-size:24px;margin:5px 0}.trace-header small{font-size:11px;letter-spacing:1px}.trace-header button{color:white;background:transparent;border:1px solid #fff8;border-radius:6px;width:40px;height:40px}.trace-notice{background:#edf4fd;margin:0;padding:12px 22px;line-height:1.5}.trace-toolbar{display:flex;gap:12px;flex-wrap:wrap;padding:15px 22px 8px;align-items:end}.trace-toolbar label{display:flex;flex-direction:column;gap:5px;flex:1;min-width:200px;font-weight:700}.trace-toolbar select{width:100%;border:1px solid #becbda;border-radius:6px;padding:9px;font-size:14px;background:white;color:#172b49}.trace-toolbar button,.trace-tabs button{padding:10px 14px;border:1px solid #becbda;border-radius:6px;background:white;color:#172b49;font-weight:700}.trace-toolbar button:disabled{opacity:.45}.trace-count,.trace-loss{margin:4px 22px 10px}.trace-loss{color:#9a3e00}.trace-tabs{display:flex;gap:8px;padding:0 22px 12px;border-bottom:1px solid #dbe3ee}.trace-tabs button[aria-pressed=true]{background:#172b49;color:white}.trace-table{overflow:auto;min-height:120px}.trace-table table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}.trace-table th{position:sticky;top:0;background:#eef2f8;padding:12px 18px}.trace-table td{border-bottom:1px solid #e5ebf2;padding:10px 18px;vertical-align:top}.trace-table small{display:block;color:#66758b;font-size:12px;margin-top:4px}.trace-empty{padding:36px;line-height:1.6}.trace-json{margin:0;padding:20px;background:#0e1d32;color:#d6e7ff;overflow:auto;font-size:12px;line-height:1.6;user-select:text}.trace-map-wrap{padding:10px 22px 22px;overflow:auto}.trace-map{position:relative;aspect-ratio:16/9;border:1px solid #b6c7dc;margin:14px 12px;background:repeating-linear-gradient(0deg,transparent 0 39px,#dce4ef 40px),repeating-linear-gradient(90deg,#f4f7fc 0 39px,#dce4ef 40px)}.trace-map>p{padding:20px}.trace-dot{position:absolute;transform:translate(-50%,-50%);min-width:23px;height:23px;display:grid;place-items:center;border-radius:50%;background:#c42539cc;color:white;font-size:10px;box-shadow:0 0 12px #c4253980}.trace-panel button:focus-visible,.trace-panel select:focus-visible{outline:3px solid #008bc5;outline-offset:2px}@media(max-width:700px){.trace-backdrop{padding:8px}.trace-panel{max-height:96vh}.trace-header,.trace-toolbar{padding:12px}.trace-notice{padding:10px 12px}.trace-table td,.trace-table th{padding:8px}.trace-toolbar label{min-width:150px}}
</style>
